def fill_row(row):
    zeros_pos = [i for i, v in enumerate(row) if v == 0]
    if not zeros_pos:
        return row[:]
    zeros_start = zeros_pos[0]
    left_val = row[zeros_start - 1]
    if left_val in CYCLE:
        start_idx = (CYCLE.index(left_val) + 1) % 5
    else:
        start_idx = 1
    fill_vals = [CYCLE[(start_idx + i) % 5] for i in range(7)]
    result = row[:]
    result[zeros_start:zeros_start + 7] = fill_vals
    return result

